"""Calculate the fleet's calibrated energy for the UTC day 2024-03-15."""

from io import StringIO
import json
from pathlib import Path

import pandas as pd


DATASET = Path("/app/dataset")
DAY_START = pd.Timestamp("2024-03-15", tz="UTC")
DAY_END = pd.Timestamp("2024-03-16", tz="UTC")


def _number(value):
    """Accept decimal-point numbers and European grouped decimal-comma numbers."""
    if pd.isna(value):
        return float("nan")
    value = str(value).strip()
    if "," in value:
        value = value.replace(".", "").replace(",", ".")
    try:
        return float(value)
    except ValueError:
        return float("nan")


def _read_production(farm_id):
    raw = (DATASET / f"production_{farm_id}.csv").read_bytes()
    encoding = "utf-16" if raw.startswith((b"\xff\xfe", b"\xfe\xff")) else "utf-8-sig"
    lines = raw.decode(encoding).splitlines()
    header = next(i for i, line in enumerate(lines) if line.startswith("timestamp"))
    separator = ";" if ";" in lines[header] else ","
    # Preserve header whitespace: some files contain two distinct columns such
    # as "output " and "output". The calibration metadata selects the right one.
    return pd.read_csv(StringIO("\n".join(lines[header:])), sep=separator, dtype=str)


def _timestamps(raw, timezone):
    result = pd.Series(pd.NaT, index=raw.index, dtype="datetime64[ns]")
    for pattern, date_format in (
        (r"\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}", "%Y-%m-%d %H:%M:%S"),
        (r"\d{2}\.\d{2}\.\d{4} \d{2}:\d{2}:\d{2}", "%d.%m.%Y %H:%M:%S"),
    ):
        selected = raw.str.fullmatch(pattern, na=False)
        result.loc[selected] = pd.to_datetime(
            raw.loc[selected], format=date_format, errors="coerce"
        )
    return result.dt.tz_localize(
        timezone, ambiguous="NaT", nonexistent="NaT"
    ).dt.tz_convert("UTC")


def _maintenance(timezone, farm_id):
    # Completed events transcribed from maintenance_notes.txt. The cancelled
    # Sakura inspection on March 15 is intentionally not an exclusion window.
    local_events = {
        "FARM_C": [("2024-03-16 08:00:00", "2024-03-16 12:00:00")],
        "FARM_F": [("2024-03-15 12:00:00", "2024-03-15 14:00:00")],
    }
    return [
        (
            pd.Timestamp(start).tz_localize(timezone).tz_convert("UTC"),
            pd.Timestamp(end).tz_localize(timezone).tz_convert("UTC"),
        )
        for start, end in local_events.get(farm_id, [])
    ]


def answer() -> dict[str, int]:
    farms = pd.read_csv(DATASET / "farms.csv")
    registry = pd.read_csv(DATASET / "farm_registry.csv")
    for frame in (farms, registry):
        frame["name_key"] = frame["farm_name"].str.strip().str.casefold()
    fleet = farms.merge(registry[["name_key", "farm_id"]], on="name_key", validate="one_to_one")
    calibration = json.loads((DATASET / "sensors_calibration.json").read_text())[
        "enterprise_platform"
    ]["deployment_environments"]["system_config"]["farms"]
    # BTU uses the international-table definition, 1055.05585262 joules.
    energy_to_kwh = {"kwh": 1.0, "mwh": 1000.0, "wh": 0.001, "btu": 1055.05585262 / 3600000}
    totals = {}

    for farm in fleet.itertuples(index=False):
        farm_id, timezone = farm.farm_id, farm.timezone
        config = calibration[farm_id]
        frame = _read_production(farm_id).drop_duplicates()
        timestamp_column = next(c for c in frame.columns if c.strip() == "timestamp")
        timestamps = _timestamps(frame[timestamp_column], timezone)
        readings = frame[config["calibration_data"]["value_column_name"]].map(_number)
        true_values = readings - config["calibration_data"]["calibration_offset"]

        # Infer the regular sampling interval before removing any faulty
        # readings, so a missing reading does not inflate a neighbor's energy.
        unique_times = timestamps.dropna().drop_duplicates().sort_values()
        intervals = unique_times.diff().dropna()
        interval_hours = (
            intervals.mode().iloc[0].total_seconds() / 3600 if not intervals.empty else 0.0
        )

        valid = timestamps.notna() & true_values.notna() & (true_values >= 0)
        temperatures = frame["inverter_temperature_C"].map(_number)
        spikes = timestamps.loc[(temperatures > 85.0) & timestamps.notna()]
        # Examine spikes across the whole export before selecting the UTC day.
        for spike in spikes:
            valid &= ~((timestamps >= spike) & (timestamps < spike + pd.Timedelta(minutes=45)))
        for start, end in _maintenance(timezone, farm_id):
            valid &= ~((timestamps >= start) & (timestamps < end))
        valid &= (timestamps >= DAY_START) & (timestamps < DAY_END)

        sensor = config["sensor_info"]
        unit = sensor["unit"].casefold()
        if sensor["reading_type"].casefold() == "power":
            power_to_kw = {"kw": 1.0, "w": 0.001, "mw": 1000.0}
            kwh_per_unit = power_to_kw[unit] * interval_hours
        else:
            kwh_per_unit = energy_to_kwh[unit]
        totals[farm_id] = round(float((true_values.loc[valid] * kwh_per_unit).sum()))

    return totals


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
